WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_growth_mixed'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '混合增长', 'kp-xingce-data-growth-mixed', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "混合增长"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "由部分合成整体时，整体增长率介于各部分增长率之间的十字交叉法则。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当材料给出由两个部分组成的一个整体时（如：进出口 = 进口 + 出口；全年 = 上半年 + 下半年），这就构成了混合模型。已知部分求整体，或已知整体求部分。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式与口诀"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不需要列复杂的方程式，牢记十字交叉三条铁律："}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 夹在中间：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 整体增速一定介于部分A和部分B的增速之间。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 偏向大基数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 整体增速不会在正中间，而是偏向于“基期量庞大”的那一方。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "3. 现期量替代：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 实战中基期量不好找，直接用“现期量”的大小去判断方向，绝大多数情况通用。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[明确题干存在 整体=A+B 模型] --> B[找出两部分的增速 a 和 b]\nB --> C[划定区间: 整体必须在 a 和 b 之间, 排除部分选项]\nC --> D[找到中点: (a+b)/2]\nD --> E[比较 A 和 B 的基期/现期绝对量谁大]\nE --> F[整体增速向绝对量大的那方倾斜, 跨过中点]\nF --> G[锁定唯一选项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 第一产业产值100亿，增速5%；第二三产业900亿，增速15%。求全省整体增速？选项：A. 4% B. 8% C. 14% D. 18%"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "夹在中间：整体必须在 5% 和 15% 之间。排除 A(4%) 和 D(18%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找中点：(5+15)/2 = 10%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看偏向：二三产业的基数极大(900 > 100)，整体被拉向 15% 这边。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定区间：增速在 10% ~ 15% 之间。排除 B(8%)，秒选 C(14%)。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "把混合增长当成简单平均：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "永远不要把两部分的增速加起来除以2就完事了！只有当两部分的基数完全一模一样时，整体增速才刚好在中间。基数不同必然倾斜。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "练习反向应用：已知整体增速是 10%，出口是 15%，那么进口必定小于 10%。熟练利用区间排除法。"}]}]}$$ AS jsonb), NULL, '混合增长的核心考点与实战推导。', category_node.id, CAST('["资料分析", "混合增长"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_growth_mixed", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
